zh:
// 固定比例：每一步都把仓位调回净值的 f 倍。
// f = 1 是满仓，0.5 是半仓，2 是两倍杠杆，负数是做空。
function decide(s, p) {
  return p.f;
}

en:
// Fixed fraction: at every step, rebalance the position back to f times wealth.
// f = 1 is fully invested, 0.5 is half invested, 2 is 2× leverage, and a negative number is short.
function decide(s, p) {
  return p.f;
}

zh:
// 买入持有：始终满仓。它是所有主动规则的参照物。
function decide(s, p) {
  return 1;
}

en:
// Buy and hold: always fully invested. It is the reference for every active rule.
function decide(s, p) {
  return 1;
}

zh:
// 均线交叉：短均线在长均线之上持有，否则空仓（或做空）。
function decide(s, p) {
  var fast = s.sma(p.fast), slow = s.sma(p.slow);
  if (!(slow === slow)) return 0;            // 数据还不够算长均线
  if (fast > slow) return p.size;
  return p.short ? -p.size : 0;
}

en:
// Moving-average crossover: hold when the short moving average is above the long one; otherwise go flat (or short).
function decide(s, p) {
  var fast = s.sma(p.fast), slow = s.sma(p.slow);
  if (!(slow === slow)) return 0;            // not enough data yet to compute the long moving average
  if (fast > slow) return p.size;
  return p.short ? -p.size : 0;
}

zh:
// 时间序列动量：过去 n 步涨了就做多，跌了就做空（或空仓）。
function decide(s, p) {
  var m = s.mom(p.n);                        // 过去 n 步的累计收益
  if (!(m === m)) return 0;
  if (m > 0) return p.size;
  return p.short ? -p.size : 0;
}

en:
// Time-series momentum: go long if the price rose over the past n steps; go short (or flat) if it fell.
function decide(s, p) {
  var m = s.mom(p.n);                        // cumulative return over the past n steps
  if (!(m === m)) return 0;
  if (m > 0) return p.size;
  return p.short ? -p.size : 0;
}

zh:
// 均值回复：价格比 n 步均线低 entry 个标准差时买入，回到 exit 以内时平仓；
// 高出 entry 个标准差时做空（可关）。
function init(p) {
  return { side: 0 };                        // 每条路径各自记住当前方向
}
function decide(s, p, st) {
  var z = s.z(p.n);                          // (价格 − 均线) / 滚动标准差
  if (!(z === z)) return 0;
  if (st.side === 0) {
    if (z < -p.entry) st.side = 1;
    else if (z > p.entry && p.short) st.side = -1;
  } else if (st.side === 1 && z > -p.exit) st.side = 0;
  else if (st.side === -1 && z < p.exit) st.side = 0;
  return st.side * p.size;
}

en:
// Mean reversion: buy when the price is entry standard deviations below its n-step moving average, and close when it is back within exit;
// go short when it is entry standard deviations above (can be turned off).
function init(p) {
  return { side: 0 };                        // each path remembers its own current side
}
function decide(s, p, st) {
  var z = s.z(p.n);                          // (price − moving average) / rolling standard deviation
  if (!(z === z)) return 0;
  if (st.side === 0) {
    if (z < -p.entry) st.side = 1;
    else if (z > p.entry && p.short) st.side = -1;
  } else if (st.side === 1 && z > -p.exit) st.side = 0;
  else if (st.side === -1 && z < p.exit) st.side = 0;
  return st.side * p.size;
}

zh:
// 固定阈值带：已知均衡价 theta。
// 对数偏离 x = ln(S/theta)。x < −width 时买入，x ≥ exit 时平仓；做空对称。
function init(p) {
  return { side: 0 };
}
function decide(s, p, st) {
  var x = Math.log(s.price / p.theta);
  var w = p.width / 100, e = p.exit / 100;
  if (st.side === 0) {
    if (x < -w) st.side = 1;
    else if (x > w && p.short) st.side = -1;
  } else if (st.side === 1 && x >= e) st.side = 0;
  else if (st.side === -1 && x <= -e) st.side = 0;
  return st.side * p.size;
}

en:
// Fixed threshold bands: the equilibrium price theta is known.
// Log deviation x = ln(S/theta). Buy when x < −width, close when x ≥ exit; shorting is symmetric.
function init(p) {
  return { side: 0 };
}
function decide(s, p, st) {
  var x = Math.log(s.price / p.theta);
  var w = p.width / 100, e = p.exit / 100;
  if (st.side === 0) {
    if (x < -w) st.side = 1;
    else if (x > w && p.short) st.side = -1;
  } else if (st.side === 1 && x >= e) st.side = 0;
  else if (st.side === -1 && x <= -e) st.side = 0;
  return st.side * p.size;
}

zh:
// OU 世界里的对数最优仓位（连续时间、无成本）：
//   f = (kappa · ln(theta / S) + sigma² / 2 − r_f) / sigma²
// kappa、theta、sigma 是你对这个世界的估计；shrink 是整体收缩系数。
function decide(s, p) {
  var sg = p.sigma / 100;
  var drift = p.kappa * Math.log(p.theta / s.price) + 0.5 * sg * sg;   // 瞬时期望收益（年率）
  return p.shrink * (drift - s.rf * s.K) / (sg * sg);                  // s.rf 是每步的无风险利率，乘以每年步数换成年率
}

en:
// Log-optimal position in the OU world (continuous time, no costs):
//   f = (kappa · ln(theta / S) + sigma² / 2 − r_f) / sigma²
// kappa, theta and sigma are your estimates of this world; shrink is the overall shrinkage factor.
function decide(s, p) {
  var sg = p.sigma / 100;
  var drift = p.kappa * Math.log(p.theta / s.price) + 0.5 * sg * sg;   // instantaneous expected return (annual rate)
  return p.shrink * (drift - s.rf * s.K) / (sg * sg);                  // s.rf is the per-step risk-free rate; multiplying by the steps per year turns it into an annual rate
}

zh:
// 波动率目标：让组合的预期波动保持在 target。
// 已实现波动高就减仓，低就加仓。
function decide(s, p) {
  var v = s.vol(p.n);                        // 最近 n 步的每步波动
  if (!(v > 0)) return 0;
  var annual = v * Math.sqrt(s.K);           // 年化
  return Math.min(p.cap, p.target / 100 / annual);
}

en:
// Volatility targeting: keep the portfolio's expected volatility at target.
// Reduce the position when realized volatility is high, add to it when it is low.
function decide(s, p) {
  var v = s.vol(p.n);                        // per-step volatility over the last n steps
  if (!(v > 0)) return 0;
  var annual = v * Math.sqrt(s.K);           // annualized
  return Math.min(p.cap, p.target / 100 / annual);
}

zh:
// 止损：价格从持仓以来的最高点回撤超过 stop 就清仓；
// 之后等价格创 n 步新高再入场。
function init(p) {
  return { inPos: true, peak: 0 };
}
function decide(s, p, st) {
  if (st.inPos) {
    if (s.price > st.peak) st.peak = s.price;
    if (s.price < st.peak * (1 - p.stop / 100)) { st.inPos = false; st.peak = 0; }
  } else if (s.t >= p.n && s.price >= s.hi(p.n)) {
    st.inPos = true; st.peak = s.price;
  }
  return st.inPos ? p.size : 0;
}

en:
// Stop-loss: close out the position when the price has drawn down by more than stop from its highest point since entry;
// then wait for the price to make a new n-step high before re-entering.
function init(p) {
  return { inPos: true, peak: 0 };
}
function decide(s, p, st) {
  if (st.inPos) {
    if (s.price > st.peak) st.peak = s.price;
    if (s.price < st.peak * (1 - p.stop / 100)) { st.inPos = false; st.peak = 0; }
  } else if (s.t >= p.n && s.price >= s.hi(p.n)) {
    st.inPos = true; st.peak = s.price;
  }
  return st.inPos ? p.size : 0;
}

zh:
// CPPI：保住净值的 floor 部分，把高出的"安全垫"放大 m 倍投入风险资产。
// 初始净值为 1，所以 floor = 80 表示保住 0.8。
function decide(s, p) {
  var cushion = s.wealth - p.floor / 100;
  if (cushion <= 0) return 0;
  return Math.min(p.cap, p.m * cushion / s.wealth);
}

en:
// CPPI: protect the floor part of wealth and invest m times the "cushion" above it in the risky asset.
// Initial wealth is 1, so floor = 80 means protecting 0.8.
function decide(s, p) {
  var cushion = s.wealth - p.floor / 100;
  if (cushion <= 0) return 0;
  return Math.min(p.cap, p.m * cushion / s.wealth);
}

zh:
// 用过去 n 步估计每步收益的均值和方差，按 shrink × (均值 − 无风险利率) / 方差 下注。
// 看看"参数要靠估计"会让 Kelly 变得多糟。
function decide(s, p) {
  var m = s.mean(p.n), v = s.vol(p.n);
  if (!(v > 0)) return 0;
  var f = p.shrink * (m - s.rf) / (v * v);
  return Math.max(-p.cap, Math.min(p.cap, f));
}

en:
// Estimate the mean and variance of the per-step return from the past n steps and bet shrink × (mean − risk-free rate) / variance.
// See how much worse Kelly gets when "the parameters have to be estimated".
function decide(s, p) {
  var m = s.mean(p.n), v = s.vol(p.n);
  if (!(v > 0)) return 0;
  var f = p.shrink * (m - s.rf) / (v * v);
  return Math.max(-p.cap, Math.min(p.cap, f));
}

zh:
// 网格：价格每比锚定价低一格就多买一份，每高一格就少一份。
// 锚定价取每条路径的起始价。
function init(p) {
  return { anchor: 0 };
}
function decide(s, p, st) {
  if (s.t === 0) st.anchor = s.price;
  var steps = Math.round(Math.log(st.anchor / s.price) / (p.grid / 100));   // 低于锚定价多少格
  return Math.max(p.minPos, Math.min(p.maxPos, p.base + p.unit * steps));
}

en:
// Grid: for each grid level the price is below the anchor price, buy one more unit; for each level above it, hold one unit less.
// The anchor price is the starting price of each path.
function init(p) {
  return { anchor: 0 };
}
function decide(s, p, st) {
  if (s.t === 0) st.anchor = s.price;
  var steps = Math.round(Math.log(st.anchor / s.price) / (p.grid / 100));   // number of grid levels below the anchor price
  return Math.max(p.minPos, Math.min(p.maxPos, p.base + p.unit * steps));
}

zh:
// 输了加倍（马丁格尔）：上一步亏了就把仓位乘以 mult，赚了就回到 base。
// 反面教材：重点看它的终值分布，而不是中位数。
function init(p) {
  return { f: p.base, w: 1 };
}
function decide(s, p, st) {
  if (s.t > 0) st.f = s.wealth < st.w ? Math.min(p.cap, st.f * p.mult) : p.base;
  st.w = s.wealth;
  return st.f;
}

en:
// Double after a loss (martingale): if the previous step lost money, multiply the position by mult; if it made money, return to base.
// A cautionary example: focus on its terminal wealth distribution rather than the median.
function init(p) {
  return { f: p.base, w: 1 };
}
function decide(s, p, st) {
  if (s.t > 0) st.f = s.wealth < st.w ? Math.min(p.cap, st.f * p.mult) : p.base;
  st.w = s.wealth;
  return st.f;
}
